-- Trial deck boxes (EN + CN), event sleeves (white + black), Korea coin back photo field fix.
insert into promo_items (id, r, data)
select v.id, v.r, v.data || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
from (values
  ('item-10645', 10645, $j${"fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "r": 10645, "id": "item-10645", "cat": "COLLECTIBLE", "nm": "Trial Decks Box (4 Decks)", "la": "English", "ev": "Global", "se": "OGN", "ty": "Trial Deck Box", "cn": "RB-01DA01-EN", "ra": "Not For Sale", "do": "All Domains", "tg": "Trial Deck\nNot For Sale\nJinx\nYasuo\nVolibear\nViktor", "pt": "Sealed white box", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/trial-decks-box-en-item-10645.webp", "pi": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/trial-decks-box-back-en-item-10645.webp", "inf": "White box (product code RB-01DA01-EN) holding all four English trial decks: Jinx, Yasuo, Volibear and Viktor. The decks were also handed out on their own, so they are listed separately too. Marking the box as owned also marks the four decks."}$j$::jsonb),
  ('item-10646', 10646, $j${"fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "r": 10646, "id": "item-10646", "cat": "COLLECTIBLE", "nm": "TCG Trial Deck Box (4 Decks)", "la": "Chinese", "ev": "China", "se": "FND", "ty": "Trial Deck Box", "cn": "FNT01-04", "ra": "Not For Sale", "do": "All Domains", "tg": "Trial Deck\nProject K\nJinx\nYasuo\nVolibear\nViktor", "pt": "Sealed white box", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/tcg-trial-deck-box-ch-item-10646.webp", "inf": "Chinese League of Legends TCG Trial Deck box (Shining Soul) holding all four Chinese trial decks, FNT01 to FNT04: Volibear, Jinx, Yasuo and Viktor. The decks also came on their own, so they are listed separately too. Marking the box as owned also marks the four decks."}$j$::jsonb),
  ('item-10647', 10647, $j${"fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "r": 10647, "id": "item-10647", "cat": "COLLECTIBLE", "nm": "League of Legends Card Sleeves (White)", "la": "English", "ev": "Event giveaway", "se": "OGN", "ty": "Sleeves", "cn": "N/A", "ra": "Limited", "do": "N/A", "tg": "Sleeves\nEvent Giveaway", "pt": "Sleeve pack", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/league-of-legends-sleeves-white-item-10647.webp", "inf": "White League of Legends card sleeves handed out at Riftbound events in limited numbers, not sold in stores. Exactly which events gave them out is still being confirmed."}$j$::jsonb),
  ('item-10648', 10648, $j${"fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "r": 10648, "id": "item-10648", "cat": "COLLECTIBLE", "nm": "League of Legends Card Sleeves (Black)", "la": "English", "ev": "Event giveaway", "se": "OGN", "ty": "Sleeves", "cn": "N/A", "ra": "Limited", "do": "N/A", "tg": "Sleeves\nEvent Giveaway", "pt": "Sleeve pack", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/league-of-legends-sleeves-black-item-10648.webp", "inf": "Black League of Legends card sleeves with gold logo, handed out at Riftbound events in limited numbers, not sold in stores. Exactly which events gave them out is still being confirmed."}$j$::jsonb)
) as v(id, r, data)
where not exists (select 1 from promo_items p where p.id = v.id);
update promo_items set data = (data - 'ii') || jsonb_build_object('pi', data->>'ii') where id = 'item-10644' and data ? 'ii';
